tf={'1':np.ones_like(t),'t':t,'sqrt':np.sqrt(t),'t2':t**2,'t1.5':t**1.5,'lnt':np.log(t),'1/t':1/t}
names=[];cols=[]
for a in Af:
    for b in tf:
        names.append(a+'*'+b); cols.append(Af[a]*tf[b])
X=np.column_stack(cols)
Xn=X/np.linalg.norm(X,axis=0)
for th in [0.01,0.03,0.1,0.2,0.3]:
    S=np.arange(X.shape[1])
    for it in range(30):
        cc,_,_,_=np.linalg.lstsq(Xn[:,S],y,rcond=None)
