        if keep.all(): break
        S=S[keep]
        if len(S)==0: break
    cc,_,_,_=np.linalg.lstsq(X[:,S],y,rcond=None)
    rr=y-X[:,S]@cc
    print('th',th,'nterms',len(S),'nmse',np.mean(rr**2)/np.var(y))
